package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.ObjectBuffer;
import com.fasterxml.jackson.databind.deser.std.StringArrayDeserializer;
import com.fasterxml.jackson.databind.deser.std.StringDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

/**
 * Unit tests for StringArrayDeserializer._deserializeCustom
 */
public class StringArrayDeserializer__deserializeCustom_TriageGen0Test {

    private StringArrayDeserializer deserializer;

    @Mock
    private JsonParser jp;

    @Mock
    private DeserializationContext ctxt;

    @Mock
    private ObjectBuffer buffer;

    @Mock
    private StringDeserializer elementDeserializer;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        deserializer = new StringArrayDeserializer();

        // Use reflection to set the protected field _elementDeserializer
        java.lang.reflect.Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
        field.setAccessible(true);
        field.set(deserializer, elementDeserializer);

        // Setup buffer mocking
        when(ctxt.leaseObjectBuffer()).thenReturn(buffer);
        when(buffer.resetAndStart()).thenReturn(new Object[1]); // Small size to test buffer expansion
    }

    @Test
    public void testDeserializeCustom_EmptyArray() throws IOException {
        // Scenario: []
        when(jp.nextToken()).thenReturn(JsonToken.END_ARRAY);
        when(buffer.completeAndClearBuffer(any(Object[].class), eq(0), eq(String.class))).thenReturn(new String[0]);

        String[] result = invokeDeserializeCustom(jp, ctxt);

        assertEquals(0, result.length);
        verify(buffer).completeAndClearBuffer(any(Object[].class), eq(0), eq(String.class));
        verify(ctxt).returnObjectBuffer(buffer);
    }

    @Test
    public void testDeserializeCustom_SingleElement() throws IOException {
        // Scenario: ["hello"]
        when(jp.nextToken())
                .thenReturn(JsonToken.VALUE_STRING)
                .thenReturn(JsonToken.END_ARRAY);
        when(elementDeserializer.deserialize(jp, ctxt)).thenReturn("hello");
        when(buffer.completeAndClearBuffer(any(Object[].class), eq(1), eq(String.class)))
                .thenReturn(new String[]{"hello"});

        String[] result = invokeDeserializeCustom(jp, ctxt);

        assertArrayEquals(new String[]{"hello"}, result);
        verify(elementDeserializer, times(1)).deserialize(jp, ctxt);
    }

    @Test
    public void testDeserializeCustom_WithNull() throws IOException {
        // Scenario: [null]
        when(jp.nextToken())
                .thenReturn(JsonToken.VALUE_NULL)
                .thenReturn(JsonToken.END_ARRAY);
        when(elementDeserializer.getNullValue()).thenReturn(null);
        when(buffer.completeAndClearBuffer(any(Object[].class), eq(1), eq(String.class)))
                .thenReturn(new String[]{null});

        String[] result = invokeDeserializeCustom(jp, ctxt);

        assertArrayEquals(new String[]{null}, result);
        verify(elementDeserializer, times(1)).getNullValue();
        verify(elementDeserializer, never()).deserialize(any(), any());
    }

    @Test
    public void testDeserializeCustom_BufferExpansion() throws IOException {
        // Scenario: ["a", "b"] where buffer size is 1
        // 1st token: VALUE_STRING -> "a"
        // 2nd token: VALUE_STRING -> "b" (triggers expansion)

        Object[] initialChunk = new Object[1];
        when(buffer.resetAndStart()).thenReturn(initialChunk);

        when(jp.nextToken())
                .thenReturn(JsonToken.VALUE_STRING)
                .thenReturn(JsonToken.VALUE_STRING)
                .thenReturn(JsonToken.END_ARRAY);

        when(elementDeserializer.deserialize(jp, ctxt)).thenReturn("a", "b");

        // Mock buffer expansion
        Object[] expandedChunk = new Object[2];
        when(buffer.appendCompletedChunk(initialChunk)).thenReturn(expandedChunk);

        // The loop logic: 
        // ix=0, token=a, chunk[0]=a, ix=1. 
        // Next token=b. ix(1) >= chunk.length(1) is true.
        // chunk = appendCompletedChunk(chunk), ix=0.
        // chunk[0]=b, ix=1.

        when(buffer.completeAndClearBuffer(eq(expandedChunk), eq(1), eq(String.class)))
                .thenReturn(new String[]{"a", "b"});

        String[] result = invokeDeserializeCustom(jp, ctxt);

        assertArrayEquals(new String[]{"a", "b"}, result);
        verify(buffer).appendCompletedChunk(initialChunk);
    }

    @Test(expected = IOException.class)
    public void testDeserializeCustom_ThrowsIOException() throws IOException {
        when(jp.nextToken()).thenThrow(new IOException("Simulated error"));
        invokeDeserializeCustom(jp, ctxt);
    }

    /**
     * Helper to access protected method via reflection
     */
    private String[] invokeDeserializeCustom(JsonParser jp, DeserializationContext ctxt) throws IOException {
        try {
            java.lang.reflect.Method method = StringArrayDeserializer.class.getDeclaredMethod(
                    "_deserializeCustom", JsonParser.class, DeserializationContext.class);
            method.setAccessible(true);
            return (String[]) method.invoke(deserializer, jp, ctxt);
        } catch (Exception e) {
            if (e.getCause() instanceof IOException) {
                throw (IOException) e.getCause();
            }
            throw new RuntimeException(e);
        }
    }
}
